    raise RuntimeError('Appium did not become ready')

def element_id(value_obj):
    if not isinstance(value_obj, dict):
        return None
    if 'error' in value_obj:
        return None
    return value_obj.get('ELEMENT') or value_obj.get('element-6066-11e4-a52e-4f735466cecf')

def find_elements(base_url, session_id, using, value):
    response = request_json(
        base_url,
        'POST',
        f'/session/{session_id}/elements',
        {'using': using, 'value': value},
    )
    values = response.get('value') or []
    if isinstance(values, dict) and 'error' in values:
        return []
    ids = []
    for item in values:
        eid = element_id(item)
        if eid:
            ids.append(eid)
    return ids

def find_element(base_url, session_id, using, value):
    ids = find_elements(base_url, session_id, using, value)
    if not ids:
        raise RuntimeError(f'not found {using}={value}')
    return ids[0]

def click(base_url, session_id, eid):
    request_json(base_url, 'POST', f'/session/{session_id}/element/{eid}/click', {})

def get_rect(base_url, session_id, eid):
